19	/**
20	 * 举报服务
21	 * Microservice version: replaces UserRepository with UserServiceClient Feign.
22	 */
23	@Service
24	public class ReportService {
25	
26	    private static final Logger logger = LoggerFactory.getLogger(ReportService.class);
27	
28	    private final ReportRepository reportRepository;
29	    private final UserServiceClient userServiceClient;
30	
31	    public ReportService(ReportRepository reportRepository, UserServiceClient userServiceClient) {
32	        this.reportRepository = reportRepository;
33	        this.userServiceClient = userServiceClient;
34	    }
35	
36	    /**
37	     * 创建举报
38	     *
39	     * @param username    举报人用户名
40	     * @param targetId    被举报目标 ID
41	     * @param targetType  目标类型 (POST / COMMENT)
42	     * @param reason      举报原因
43	     * @param description 补充描述（拼接到 reason 中）
44	     * @return 保存后的 Report 实体
45	     */
46	    @Transactional
47	    public Report createReport(String username, Long targetId, String targetType, String reason, String description) {
48	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
49	        if (user == null || user.getId() == null) {
50	            throw new ResourceNotFoundException("用户不存在");
51	        }
52	
53	        Report.TargetType type = Report.TargetType.valueOf(targetType.toUpperCase());
54	
55	        // Append description to reason
56	        String fullReason = reason;
57	        if (description != null && !description.trim().isEmpty()) {
58	            fullReason = reason + " | " + description;
59	        }
60	
61	        Report report = new Report(user.getId(), type, targetId, fullReason);
62	        report = reportRepository.save(report);
63	
64	        logger.info("举报创建成功: id={}, reporter={}, targetType={}, targetId={}",
65	                report.getId(), username, targetType, targetId);
66	
67	        return report;
68	    }
69	
70	    /**
71	     * 管理员获取举报列表（按状态筛选，分页）
72	     *
73	     * @param status 举报状态（为空则查全部）
74	     * @param page   页码
75	     * @param size   每页条数
76	     * @return 分页举报列表
77	     */
78	    @Transactional(readOnly = true)
79	    public Page<Report> getReports(String status, int page, int size) {
80	        Pageable pageable = PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, "createdAt"));
81	
82	        if (status == null || status.trim().isEmpty()) {
83	            return reportRepository.findAllByOrderByCreatedAtDesc(pageable);
84	        }
85	
86	        Report.ReportStatus reportStatus = Report.ReportStatus.valueOf(status.toUpperCase());
87	        return reportRepository.findByStatusOrderByCreatedAtDesc(reportStatus, pageable);
88	    }
89	
90	    /**
91	     * 管理员处理举报
92	     *
93	     * @param id     举报 ID
94	     * @param status 处理后状态 (RESOLVED / REVIEWED)
95	     * @return 更新后的 Report 实体
96	     */
97	    @Transactional
98	    public Report handleReport(Long id, String status) {
99	        Report report = reportRepository.findById(id)
100	                .orElseThrow(() -> new ResourceNotFoundException("举报不存在"));
101	
102	        report.setStatus(Report.ReportStatus.valueOf(status.toUpperCase()));
103	        report.setReviewedAt(LocalDateTime.now());
104	        report = reportRepository.save(report);
105	
106	        logger.info("举报处理完成: id={}, status={}", id, status);
107	
108	        return report;
109	    }
110	}
